// Generated by AI (UnitTest MCP)
//! Request-scoped identity shared by the MindLeak and Lodestar MCP planes.

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};

const TOKEN_HEX_LEN: usize = 32;
const AGENT_DIGEST_BYTES: usize = 16;

/// Longest accepted declared value. Branch names and shas are short; anything
/// longer is a client bug, and this registry is memory the client can grow.
const MAX_CONTEXT_FIELD_LEN: usize = 256;

/// Where a session is working, as *declared* by the client (ADR-0035).
///
/// Every field is optional and self-reported. The server never inspects git or
/// the filesystem to fill one in: a stdio server may not share the agent's
/// working directory, and a linked worktree's branch differs from the database
/// root. A session that declares nothing leaves every field `None`, which
/// callers report as `unknown` rather than guessing.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct SessionContext {
    pub branch: Option<String>,
    pub head_sha: Option<String>,
    pub base: Option<String>,
    pub dirty: Option<bool>,
    /// Commits this session's head is behind its declared base, as counted by
    /// the client (ADR-0043). Declared rather than derived: the server is
    /// forbidden from reading Git, and branch/head/base can only reveal that
    /// two commits *differ*, never the distance between them.
    pub behind: Option<i64>,
}

impl SessionContext {
    /// Read the optional `branch` / `head_sha` / `base` / `dirty` a client
    /// declared on an `open_session` call. Both MCP planes accept the same
    /// shape, so the parse lives with the type rather than in each server.
    ///
    /// Absent fields stay `None`. A present field of the wrong type, or a
    /// blank or over-long string, is an error rather than a silent drop: the
    /// client asked for something it did not get, and should hear about it.
    pub fn from_arguments(arguments: &Value) -> Result<Self, String> {
        Ok(Self {
            branch: declared_string(arguments, "branch")?,
            head_sha: declared_string(arguments, "head_sha")?,
            base: declared_string(arguments, "base")?,
            dirty: match arguments.get("dirty") {
                None | Some(Value::Null) => None,
                Some(Value::Bool(flag)) => Some(*flag),
                Some(_) => return Err("dirty must be a boolean".to_string()),
            },
            behind: match arguments.get("behind") {
                None | Some(Value::Null) => None,
                Some(Value::Number(count)) => match count.as_i64() {
                    Some(count) if count >= 0 => Some(count),
                    _ => return Err("behind must be a non-negative integer".to_string()),
                },
                Some(_) => return Err("behind must be a non-negative integer".to_string()),
            },
        })
    }

    /// Whether the client declared anything at all.
    pub fn is_declared(&self) -> bool {
        self.branch.is_some()
            || self.head_sha.is_some()
            || self.base.is_some()
            || self.dirty.is_some()
            || self.behind.is_some()
    }

    /// The declared fields as JSON, or `None` when nothing was declared.
    ///
    /// Absent fields are omitted rather than emitted as `null`, so a session
    /// that declares nothing produces no `context` at all and existing clients
    /// see exactly the response they saw before ADR-0035.
    pub fn declared_json(&self) -> Option<Value> {
        if !self.is_declared() {
            return None;
        }
        let mut declared = serde_json::Map::new();
        for (field, value) in [
            ("branch", self.branch.as_ref()),
            ("head_sha", self.head_sha.as_ref()),
            ("base", self.base.as_ref()),
        ] {
            if let Some(value) = value {
                declared.insert(field.to_string(), Value::String(value.clone()));
            }
        }
        if let Some(dirty) = self.dirty {
            declared.insert("dirty".to_string(), Value::Bool(dirty));
        }
        if let Some(behind) = self.behind {
            declared.insert("behind".to_string(), Value::Number(behind.into()));
        }
        Some(Value::Object(declared))
    }
}

/// The `open_session` input schema, shared by both MCP planes so the declared
/// working-context contract cannot drift between them (ADR-0035).
pub fn session_input_schema() -> Value {
    serde_json::json!({
        "type": "object",
        "properties": {
            "session_id": { "type": "string", "pattern": "^[0-9a-f]{32}$" },
            "branch": {
                "type": "string",
                "description": "Optional. Branch this session is working on. Declared by the client; never detected by the server."
            },
            "head_sha": {
                "type": "string",
                "description": "Optional. Commit this session is working from."
            },
            "base": {
                "type": "string",
                "description": "Optional. Base this session expects to merge into, e.g. origin/main."
            },
            "dirty": {
                "type": "boolean",
                "description": "Optional. Whether the working tree had uncommitted changes when declared."
            },
            "behind": {
                "type": "integer",
                "minimum": 0,
                "description": "Optional. Commits this head is behind the declared base, counted by the client. The server never reads Git, so an undeclared value reports as unknown rather than being guessed (ADR-0043)."
            }
        },
        "required": ["session_id"]
    })
}

fn declared_string(arguments: &Value, field: &str) -> Result<Option<String>, String> {
    match arguments.get(field) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::String(raw)) => {
            let value = raw.trim();
            if value.is_empty() {
                return Err(format!("{field} must not be blank when declared"));
            }
            if value.len() > MAX_CONTEXT_FIELD_LEN {
                return Err(format!(
                    "{field} must be at most {MAX_CONTEXT_FIELD_LEN} characters"
                ));
            }
            Ok(Some(value.to_string()))
        }
        Some(_) => Err(format!("{field} must be a string")),
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SessionIdentity {
    pub agent_id: String,
    pub context: SessionContext,
}

#[derive(Clone)]
pub struct SessionRegistry {
    base: Arc<str>,
    registered: Arc<RwLock<HashMap<[u8; 32], SessionContext>>>,
}

impl SessionRegistry {
    pub fn new(base: &str) -> Result<Self, String> {
        let base = base.trim();
        if base.is_empty()
            || !base
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "._-".contains(character))
        {
            return Err(
                "session agent base must contain only ASCII letters, digits, '.', '_', or '-'"
                    .to_string(),
            );
        }
        Ok(Self {
            base: Arc::from(base),
            registered: Arc::new(RwLock::new(HashMap::new())),
        })
    }

    /// Register a token and record the context it declares.
    ///
    /// Re-declaring replaces the stored context, which is how a session
    /// refreshes after switching branch or committing: the client is the source
    /// of truth, so declaring nothing clears what was declared before.
    pub fn open_session(
        &self,
        token: &str,
        context: SessionContext,
    ) -> Result<SessionIdentity, String> {
        let digest = token_digest(token)?;
        self.registered
            .write()
            .map_err(|_| "session registry lock poisoned".to_string())?
            .insert(digest, context.clone());
        Ok(self.identity_for(digest, context))
    }

    pub fn resolve(&self, token: &str) -> Result<SessionIdentity, String> {
        let digest = token_digest(token)?;
        let registered = self
            .registered
            .read()
            .map_err(|_| "session registry lock poisoned".to_string())?;
        let Some(context) = registered.get(&digest) else {
            return Err("unknown session_id; call open_session first".to_string());
        };
        Ok(self.identity_for(digest, context.clone()))
    }

    fn identity_for(&self, digest: [u8; 32], context: SessionContext) -> SessionIdentity {
        let fingerprint = digest[..AGENT_DIGEST_BYTES]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        SessionIdentity {
            agent_id: format!("session:v1:{}:{fingerprint}", self.base),
            context,
        }
    }
}

fn token_digest(token: &str) -> Result<[u8; 32], String> {
    if token.len() != TOKEN_HEX_LEN
        || !token
            .chars()
            .all(|character| character.is_ascii_hexdigit() && !character.is_ascii_uppercase())
    {
        return Err("session_id must be exactly 32 lowercase hexadecimal characters".to_string());
    }
    Ok(Sha256::digest(token.as_bytes()).into())
}

pub fn compatible_legacy_owner(expected_owner: &str, target_agent: &str) -> bool {
    let Some(rest) = target_agent.strip_prefix("session:v1:") else {
        return false;
    };
    let Some((base, fingerprint)) = rest.rsplit_once(':') else {
        return false;
    };
    if fingerprint.len() != AGENT_DIGEST_BYTES * 2
        || !fingerprint
            .chars()
            .all(|character| character.is_ascii_hexdigit())
    {
        return false;
    }
    if expected_owner == base {
        return true;
    }
    expected_owner
        .strip_prefix(&format!("{base}-"))
        .is_some_and(|nonce| nonce.len() == 8 && nonce.chars().all(|c| c.is_ascii_hexdigit()))
}

#[cfg(test)]
mod tests {
    use super::*;

    use serde_json::json;

    const SESSION_A: &str = "00112233445566778899aabbccddeeff";
    const SESSION_B: &str = "ffeeddccbbaa99887766554433221100";

    fn on_branch(branch: &str) -> SessionContext {
        SessionContext {
            branch: Some(branch.to_string()),
            head_sha: Some("7723f78".to_string()),
            base: Some("origin/main".to_string()),
            dirty: Some(true),
            behind: Some(2),
        }
    }

    #[test]
    fn registration_is_required_and_idempotent() {
        let registry = SessionRegistry::new("copilot").unwrap();
        assert!(registry.resolve(SESSION_A).is_err());

        let first = registry
            .open_session(SESSION_A, SessionContext::default())
            .unwrap();
        let retry = registry
            .open_session(SESSION_A, SessionContext::default())
            .unwrap();
        assert_eq!(retry, first);
        assert_eq!(registry.resolve(SESSION_A).unwrap(), first);
    }

    #[test]
    fn logical_sessions_are_distinct_but_restart_stable() {
        let first_process = SessionRegistry::new("copilot").unwrap();
        let first = first_process
            .open_session(SESSION_A, SessionContext::default())
            .unwrap();
        let second = first_process
            .open_session(SESSION_B, SessionContext::default())
            .unwrap();
        assert_ne!(first, second);

        let restarted = SessionRegistry::new("copilot").unwrap();
        assert_eq!(
            restarted
                .open_session(SESSION_A, SessionContext::default())
                .unwrap(),
            first
        );
    }

    // ADR-0035 decision 6: a session that declares nothing behaves exactly as it
    // did before working context existed, and reports absence rather than a guess.
    #[test]
    fn an_undeclared_session_reports_nothing_rather_than_guessing() {
        let registry = SessionRegistry::new("copilot").unwrap();
        let identity = registry
            .open_session(SESSION_A, SessionContext::default())
            .unwrap();

        assert!(!identity.context.is_declared());
        assert_eq!(identity.context.branch, None);
        assert_eq!(identity.context.head_sha, None);
        assert_eq!(identity.context.base, None);
        assert_eq!(identity.context.dirty, None);
        assert_eq!(identity.context.behind, None);
        assert_eq!(registry.resolve(SESSION_A).unwrap(), identity);
    }

    // ADR-0035 decision 1: declared context round-trips under the same token,
    // including across a restart, because the client re-declares it and identity
    // is derived from the token rather than process state.
    #[test]
    fn declared_context_round_trips_under_the_same_token() {
        let registry = SessionRegistry::new("copilot").unwrap();
        let declared = registry
            .open_session(SESSION_A, on_branch("fleet/typed-controls"))
            .unwrap();

        assert_eq!(declared.context, on_branch("fleet/typed-controls"));
        assert!(declared.context.is_declared());
        assert_eq!(
            registry.resolve(SESSION_A).unwrap().context.branch.unwrap(),
            "fleet/typed-controls"
        );

        let restarted = SessionRegistry::new("copilot").unwrap();
        let after_restart = restarted
            .open_session(SESSION_A, on_branch("fleet/typed-controls"))
            .unwrap();
        assert_eq!(after_restart, declared);
    }

    // ADR-0035 decision 2: declared once and refreshed on change. The client owns
    // the truth, so a later declaration replaces the earlier one outright —
    // including back to nothing when the client stops declaring.
    #[test]
    fn re_declaring_replaces_the_stored_context() {
        let registry = SessionRegistry::new("copilot").unwrap();
        registry
            .open_session(SESSION_A, on_branch("fleet/typed-controls"))
            .unwrap();

        registry.open_session(SESSION_A, on_branch("main")).unwrap();
        assert_eq!(
            registry.resolve(SESSION_A).unwrap().context.branch.unwrap(),
            "main"
        );

        registry
            .open_session(SESSION_A, SessionContext::default())
            .unwrap();
        assert!(!registry.resolve(SESSION_A).unwrap().context.is_declared());
    }

    // Context is per token: one session's branch must never leak into another's.
    #[test]
    fn context_is_scoped_to_its_own_token() {
        let registry = SessionRegistry::new("copilot").unwrap();
        registry
            .open_session(SESSION_A, on_branch("fleet/typed-controls"))
            .unwrap();
        registry
            .open_session(SESSION_B, SessionContext::default())
            .unwrap();

        assert_eq!(
            registry.resolve(SESSION_A).unwrap().context.branch.unwrap(),
            "fleet/typed-controls"
        );
        assert!(!registry.resolve(SESSION_B).unwrap().context.is_declared());
    }

    // Context is client-supplied, so the parse is a boundary: absent stays
    // absent, and a wrong type or a blank value is reported rather than dropped.
    #[test]
    fn declared_arguments_parse_or_report_why_not() {
        let none = SessionContext::from_arguments(&json!({ "session_id": SESSION_A })).unwrap();
        assert!(!none.is_declared());

        let full = SessionContext::from_arguments(&json!({
            "branch": "  fleet/typed-controls  ",
            "head_sha": "7723f78",
            "base": "origin/main",
            "dirty": true,
            "behind": 3,
        }))
        .unwrap();
        assert_eq!(full.branch.unwrap(), "fleet/typed-controls");
        assert_eq!(full.head_sha.unwrap(), "7723f78");
        assert_eq!(full.base.unwrap(), "origin/main");
        assert_eq!(full.dirty, Some(true));
        assert_eq!(full.behind, Some(3));

        // Zero is a real answer: "declared, and up to date" is not "unknown".
        let current = SessionContext::from_arguments(&json!({ "behind": 0 })).unwrap();
        assert_eq!(current.behind, Some(0));
        assert!(current.is_declared());

        let explicit_null =
            SessionContext::from_arguments(&json!({ "branch": Value::Null })).unwrap();
        assert_eq!(explicit_null.branch, None);

        assert!(SessionContext::from_arguments(&json!({ "branch": "   " })).is_err());
        assert!(SessionContext::from_arguments(&json!({ "branch": 7 })).is_err());
        assert!(SessionContext::from_arguments(&json!({ "dirty": "yes" })).is_err());
        assert!(SessionContext::from_arguments(&json!({ "behind": -1 })).is_err());
        assert!(SessionContext::from_arguments(&json!({ "behind": "two" })).is_err());
        assert!(SessionContext::from_arguments(&json!({ "head_sha": "a".repeat(257) })).is_err());
    }

    #[test]
    fn malformed_tokens_and_bases_are_rejected() {
        let registry = SessionRegistry::new("copilot").unwrap();
        for token in [
            "short",
            "00112233445566778899AABBCCDDEEFF",
            "00112233445566778899aabbccddeefg",
        ] {
            assert!(registry
                .open_session(token, SessionContext::default())
                .is_err());
        }
        assert!(SessionRegistry::new("copilot:unsafe").is_err());
    }

    #[test]
    fn only_compatible_legacy_owners_can_transfer() {
        let agent = SessionRegistry::new("copilot")
            .unwrap()
            .open_session(SESSION_A, SessionContext::default())
            .unwrap()
            .agent_id;
        assert!(compatible_legacy_owner("copilot", &agent));
        assert!(compatible_legacy_owner("copilot-abcd1234", &agent));
        assert!(!compatible_legacy_owner("claude-abcd1234", &agent));
        assert!(!compatible_legacy_owner("copilot-nothex!!", &agent));
        assert!(!compatible_legacy_owner("copilot-abcd1234", "copilot-new"));
    }
}
